"""Writes bend_sss_gpu.slangh from the unmodified bend_sss_gpu.h.

Slang rejects the C-style elaborated type 'struct DispatchParameters' in parameter lists, which the DirectX compiler accepts.
The conversion only drops that keyword there; everything else, including the license header, is copied as is.
Run from any directory: python ConvertForSlang.py
"""

import pathlib
import re

Folder = pathlib.Path(__file__).resolve().parent
Source = (Folder / "bend_sss_gpu.h").read_text(encoding="utf-8")
Converted, Count = re.subn(r"([(,]\s*)struct\s+DispatchParameters\b", r"\1DispatchParameters", Source)
if Count == 0:
    raise SystemExit("No parameter lists use 'struct DispatchParameters'; check whether the upstream file changed")

# Slang member functions may only assign members when marked mutating.
Converted, Mutating = re.subn(r"(\n\s*)void SetDefaults\(\)", r"\1[mutating] void SetDefaults()", Converted)
if Mutating != 1:
    raise SystemExit("Expected one SetDefaults(); check whether the upstream file changed")

Notice = "// Generated by ConvertForSlang.py from bend_sss_gpu.h for Slang: 'struct' is dropped from DispatchParameters parameters and SetDefaults() is marked mutating. Do not edit.\n"
(Folder / "bend_sss_gpu.slangh").write_text(Notice + Converted, encoding="utf-8", newline="")
print(f"Converted {Count} parameter declarations")
